//! Parity tests for `gpt_sovits_text::cantonese` against golden fixtures
//! generated by `parity/cantonese/gen_fixtures.py`.
//!
//! Every field is compared exactly, including the exception type and message
//! where Python raises.

use gpt_sovits_text::cantonese::{
  Error, g2p, get_jyutping, jyuping_to_initials_finals_tones, replace_punctuation, text_normalize,
};
use serde_json::{Value, json};

const SENTENCES: &str = include_str!("fixtures/cantonese/sentences.jsonl");
const SYLLABLES: &str = include_str!("fixtures/cantonese/syllables.jsonl");

/// Inputs whose Rust output is known to differ from Python. They must be
/// documented in `parity/README.md`; currently there are none.
const KNOWN_MISMATCHES: &[&str] = &[];

fn err_json(e: Error) -> Value {
  let msg = match &e {
    Error::KeyError(m) | Error::ValueError(m) | Error::TypeError(m) | Error::IndexError(m) => {
      m.clone()
    }
  };
  json!({ "e": [e.name(), msg] })
}

fn to_json<T: serde::Serialize>(r: Result<T, Error>) -> Value {
  match r {
    Ok(v) => json!({ "o": v }),
    Err(e) => err_json(e),
  }
}

fn g2p_json(r: Result<(Vec<String>, Vec<usize>), Error>) -> Value {
  to_json(r.map(|(p, w)| json!([p, w])))
}

fn lines(s: &str) -> impl Iterator<Item = Value> + '_ {
  s.lines().map(|l| serde_json::from_str(l).unwrap())
}

#[test]
fn sentences() {
  let mut n = 0;
  let mut per_field = [0usize; 5];
  let mut mismatches: Vec<String> = Vec::new();
  for case in lines(SENTENCES) {
    n += 1;
    let text = case["i"].as_str().unwrap();
    let rp = json!(replace_punctuation(text));
    let norm_r = text_normalize(text);
    let (norm, jy, g2p_norm) = match &norm_r {
      Ok(norm) => (
        json!({ "o": norm }),
        to_json(get_jyutping(norm)),
        g2p_json(g2p(norm)),
      ),
      Err(e) => (err_json(e.clone()), Value::Null, Value::Null),
    };
    let raw = g2p_json(g2p(text));
    let got = [rp, norm, jy, g2p_norm, raw];
    let fields = ["rp", "norm", "jy", "g2p", "raw_g2p"];
    let mut ok = true;
    for (i, (field, got)) in fields.iter().zip(&got).enumerate() {
      if &case[*field] == got {
        per_field[i] += 1;
      } else {
        ok = false;
        if mismatches.len() < 20 {
          eprintln!(
            "{field} mismatch for {text:?}:\n  want {}\n  got  {got}",
            case[*field]
          );
        }
      }
    }
    if !ok {
      mismatches.push(text.to_string());
    }
  }
  for (field, m) in ["rp", "norm", "jy", "g2p", "raw_g2p"].iter().zip(per_field) {
    eprintln!("sentences.jsonl {field}: {m}/{n}");
  }
  assert!(n >= 3000, "only {n} sentence cases");
  assert_eq!(
    mismatches,
    KNOWN_MISMATCHES,
    "{} mismatches",
    mismatches.len()
  );
}

#[test]
fn syllables() {
  let mut n = 0;
  let mut mismatches = Vec::new();
  for case in lines(SYLLABLES) {
    n += 1;
    let input: Vec<String> = case["i"]
      .as_array()
      .unwrap()
      .iter()
      .map(|s| s.as_str().unwrap().to_string())
      .collect();
    let got = g2p_json(jyuping_to_initials_finals_tones(&input));
    let mut want = case.clone();
    want.as_object_mut().unwrap().remove("i");
    if got != want {
      if mismatches.len() < 20 {
        eprintln!("mismatch for {input:?}:\n  want {want}\n  got  {got}");
      }
      mismatches.push(input);
    }
  }
  eprintln!("syllables.jsonl: {}/{n}", n - mismatches.len());
  assert!(mismatches.is_empty(), "{} mismatches", mismatches.len());
}
